22.query:
fetch user.events
| summarize count = count(), by:{view.name}
| sort count desc

31.query:
fetch user.events
| summarize count = count(), by:{dt.rum.instance.id}
| join [ 
  fetch user.events, from:-30d, to:-24h
  | summarize count = count(), by:{dt.rum.instance.id}
  ], on:{dt.rum.instance.id}
| summarize countOld=count()
| fieldsAdd j=1
| join [
  fetch user.events
  | summarize countAll = countDistinctExact(dt.rum.instance.id)
  | fieldsAdd j=1
], on:{j}
| fieldsAdd newCount=right.countAll-countOld

35.query:
fetch user.events
| filter event_properties.name == "tabshop.Purchase acknowledged!"
| summarize count=countDistinctExact(dt.rum.instance.id), by:{}
